PREFIX imxgeo: <http://modellen.geostandaarden.nl/def/imx-geo#>
SELECT ?per ?sectie ?perceelnummer WHERE {
  ?adres a imxgeo:Adres ;
    imxgeo:postcode "1234AB" ;
    imxgeo:huisnummer 10 ;
    imxgeo:isAdresVanGebouw ?geb .
  ?geb imxgeo:bevindtZichOpPerceel ?per .
  ?per <https://modellen.kkg.kadaster.nl/def/imxgeo-ext#sectie> ?sectie ;
       <https://modellen.kkg.kadaster.nl/def/imxgeo-ext#perceelnummer> ?perceelnummer .
} LIMIT 5

PREFIX imxgeo: <http://modellen.geostandaarden.nl/def/imx-geo#>
PREFIX ext: <https://modellen.kkg.kadaster.nl/def/imxgeo-ext#>
SELECT ?per WHERE {
  ?per a imxgeo:Perceel ;
    ext:sectie "A" ;
    ext:perceelnummer 123 ;
    imxgeo:ligtInRegistratieveRuimte ?plaats .
  ?plaats imxgeo:naam ?plaatsnaam .
  FILTER(CONTAINS(LCASE(?plaatsnaam), LCASE("Utrecht")))
} LIMIT 5

PREFIX imxgeo: <http://modellen.geostandaarden.nl/def/imx-geo#>
SELECT ?grondslagcode ?grondslag WHERE {
  ?beperking imxgeo:isBeperkingOpPerceel <PERCEEL_URI> ;
    imxgeo:grondslagcode ?grondslagcode ;
    imxgeo:grondslag ?grondslag .
} LIMIT 5

SELECT DISTINCT ?type (COUNT(?s) as ?cnt) WHERE {
  ?s a ?type .
} GROUP BY ?type ORDER BY DESC(?cnt) LIMIT 20
